FUNCTION handleCreateProject(request):
    // REQ-5-013; preconditions: JSON and persistence available.
    REQUIRE user or admin OR RETURN 401; REQUIRE JSON OR RETURN 415; VALIDATE REQ-5-002 OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF key exists THEN ROLLBACK; RETURN 409. END IF CREATE project and caller creator membership; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback preserves projects and memberships.

FUNCTION handlePatchProject(request, project_id):
    // REQ-5-015; preconditions: JSON, existing project, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE result OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF duplicate key or deactivation has active tickets THEN ROLLBACK; RETURN 409. END IF UPDATE; COMMIT; RETURN 200.
    // Idempotent identical payload; rollback leaves project relations unchanged.

FUNCTION handleDeleteProject(request, project_id):
    // REQ-5-016; preconditions: existing project and persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; RETURN 404 for invalid or absent id. BEGIN TRANSACTION; IF tickets or non-creator memberships exist THEN ROLLBACK; RETURN 409. END IF MARK deleted; COMMIT; RETURN 204.
    // REQ-5-008; repeat is 404 and rollback preserves all relationships.

FUNCTION handleCreateMembership(request, project_id):
    // REQ-5-018; preconditions: JSON, existing project and account, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE ids OR RETURN 400 or 422; unknown project or account is 404.
    BEGIN TRANSACTION; IF membership exists THEN ROLLBACK; RETURN 409. END IF CREATE active membership; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback preserves project-ticket relations.

FUNCTION handleDeleteMembership(request, project_id, membership_id):
    // REQ-5-019; preconditions: matching existing memberships and persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; RETURN 404 for invalid, absent, or mismatched ids. BEGIN TRANSACTION; IF creator membership or active assignment exists THEN ROLLBACK; RETURN 409. END IF DEACTIVATE membership; COMMIT; RETURN 204.
    // REQ-5-005; non-idempotent and rollback preserves ticket-assignee relations.

FUNCTION handleCreateTicket(request):
    // REQ-5-021; preconditions: JSON, active project, persistence available.
    REQUIRE active membership or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE body OR RETURN 400 or 422; missing or inactive project is 404.
    BEGIN TRANSACTION; CREATE TODO ticket with caller as creator; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback preserves project and membership relations.

FUNCTION handlePatchTicket(request, ticket_id):
    // REQ-5-023; preconditions: JSON, existing ticket, persistence available.
    REQUIRE eligible actor or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE nonempty partial result OR RETURN 400 or 422.
    BEGIN TRANSACTION; UPDATE supplied content only; COMMIT; RETURN 200.
    // Identical payload idempotent; rollback preserves assignment, state, and project relations.

FUNCTION handleAssignTicket(request, ticket_id):
    // REQ-5-024; preconditions: JSON, existing ticket, persistence available.
    REQUIRE ticket creator, project creator, or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE target OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF target membership absent, inactive, or other project THEN ROLLBACK; RETURN 404 or 409. END IF SET assignee; COMMIT; RETURN 200.
    // REQ-5-005; identical target idempotent and rollback preserves all relations.

FUNCTION handleTransitionTicket(request, ticket_id):
